// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _test(address _target, uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _value);
        uint balBefore = address(c).balance;
        try c.sendMoney(_target, _value) {} catch { return; }
        uint balAfter = address(c).balance;
        assertTrue(balAfter == balBefore - _value);
    }

    function testFuzz_test(address _target, uint256 _value) public {
        _test(_target, _value);
    }

    receive() external payable {}
}
